+			return racecontext.StandingsEntry{}, nil
+		}
+		return racecontext.StandingsEntry{}, fmt.Errorf("redis hget standings: %w", err)
+	}
+	var entry racecontext.StandingsEntry
+	if err := json.Unmarshal([]byte(raw), &entry); err != nil {
+		return racecontext.StandingsEntry{}, nil
+	}
+	return entry, nil
+}
