	return o.recordEvent(ctx, runevents.[REDACTED:secret.entropy], payload, runevents.SummaryMetadata{
		Status:        "failed",
		StepIndex:     o.currentStep(),
		EvidenceLevel: runevents.[REDACTED:secret.entropy],
